/**
 * 고정 PHMSA Cushing 사고 날짜 목록을 검사한다. 주 전체를 Cushing으로 바꾸지 않는다.
 * @param value 091-PHMSA-Z 런 JSON.
 * @returns 검증된 사고 목록 또는 오류 상태.
 */
export function readCushingPhmsa(value: unknown): CushingPhmsaSeries | null {
  const v = value as { runId?: unknown; geography?: unknown; system?: unknown; rows?: CushingPhmsaIncident[] };
  if (!v || v.runId !== RUN_ID || v.geography !== GEOGRAPHY || v.system !== SYSTEM) return null;
  if (!Array.isArray(v.rows) || v.rows.length !== EXPECTED.length) return null;
  for (let i = 0; i < EXPECTED.length; i++) {
    const row = v.rows[i] as CushingPhmsaIncident;
    const [incidentDate, reportNumber, cause, narrative, fatalities, injuries] = EXPECTED[i];
    if (!row || row.incidentDate !== incidentDate || row.reportNumber !== reportNumber) return null;
    if (row.system !== SYSTEM || row.cause !== cause || row.narrative !== narrative) return null;
    if (row.fatalities !== fatalities || row.injuries !== injuries) return null;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(row.incidentDate)) return null;
    if (i > 0) {
      const prev = v.rows[i - 1] as CushingPhmsaIncident;
      if (prev.incidentDate > row.incidentDate) return null;
      if (prev.incidentDate === row.incidentDate && prev.reportNumber >= row.reportNumber) return null;
    }
  }
  return v as CushingPhmsaSeries;
}

/**
 * 지정 날짜의 Cushing 사고를 꺼낸다. 하루에 여러 건이 있을 수 있다.
 * @param series 검증된 PHMSA Cushing 사고 목록.
 * @param incidentDate 날짜 (예: 2025-12-08).
 * @returns 해당 날짜 행 목록 또는 없으면 빈 배열.
 */
export function phmsaIncidentsOn(series: CushingPhmsaSeries | null, incidentDate: string): CushingPhmsaIncident[] {
  if (!series || series.runId !== RUN_ID) return [];
  return series.rows.filter((r) => r.incidentDate === incidentDate);
}
